#include <bits/stdc++.h>
using namespace std;

const __int128 MODULUS = 998244353;

__int128 mod_pow(__int128 base, __int128 exp, __int128 mod) {
    __int128 result = 1;
    __int128 b = base % mod;
    __int128 e = exp;
    while (e > 0) {
        if (e & 1) result = (result * b) % mod;
        b = (b * b) % mod;
        e >>= 1;
    }
    return result;
}

__int128 mod_inverse(__int128 a, __int128 m) {
    // Fermat's little theorem since m is prime
    return mod_pow(a, m - 2, m);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    // Read the first line (number of test cases), but it's not used
    getline(cin, line);
    int testCases = 1;
    // testCases = stoi(line);
    while (testCases-- > 0) {
        getline(cin, line);
        stringstream ss(line);
        long long n, m;
        ss >> n >> m;
        getline(cin, line);
        ss.clear();
        ss.str(line);
        long long l, r;
        ss >> l >> r;
        long long segmentLength = r - l;
        long long evenCount = segmentLength / 2 + 1;
        long long oddCount = (segmentLength + 1) / 2;
        __int128 totalExp = (__int128)(n) * m;
        if ((n * m) % 2 == 1) {
            __int128 base = segmentLength + 1;
            __int128 answer = mod_pow(base, totalExp, MODULUS);
            cout << (long long)answer << "\n";
        } else {
            __int128 sumPower = mod_pow(evenCount + oddCount, totalExp, MODULUS);
            __int128 diffPower = mod_pow(evenCount - oddCount, totalExp, MODULUS);
            __int128 totalSum = (sumPower + diffPower) % MODULUS;
            __int128 invTwo = mod_inverse(2, MODULUS);
            __int128 finalResult = (totalSum * invTwo) % MODULUS;
            cout << (long long)finalResult << "\n";
        }
    }
    return 0;
}
